/// <summary>
/// CB233_TOReceiptDetails
/// </summary>
[DataContractAttribute]
class METBaseMultiResponseContract
{
    private List responses;
   
}

Method.Source:
    /// <summary>
    /// Parm method for a list of responses
    /// </summary>
    /// <param name = "_responses">Set list of responses</param>
    /// <returns>Get list of responses</returns>
    [DataMemberAttribute("Responses"),
    DataCollection(Types::Class, classStr(METBaseResponseContract)),
    AifCollectionTypeAttribute('_responses', Types::Class, classStr(METBaseResponseContract)),
    AifCollectionTypeAttribute('return', Types::Class, classStr(METBaseResponseContract))]    
    public List parmResponses(List _responses = responses)
    {
        if (!prmIsDefault(_responses))
        {
            responses = _responses;
        }

        return responses;
    }
